// function replaceAll(str, search, replacement) mein teen strings do
// Agar koi bhi string nahi: ""
// Agar search empty: original string
// Warna replaceAll use karo

solution:
function replaceAll(str, search, replacement) {
  if (typeof str !== "string" || typeof search !== "string" || typeof replacement !== "string") return ""
  if (search.length === 0) return str
  return str.replaceAll(search, replacement)
}
